# Builds ds.css: the CYP design system (artifact "CYP", type Design System) laid over the styles of CYP EDU.
# Tokens come from tokens.json of the system; fonts are embedded so the app opens without internet.
import base64, json, sys
D = '/home/claude/ds2/CYP/'   # live artifact, version 1795461288-db2b, read on 23/11/2026
T = json.load(open(D + 'tokens.json'))
# tokens.css of the system (generated there from tokens.json): every variable and the type classes. Its @font-face rules are left out:
# the app ships five of the eight files and embeds them, so the rules are written here for those five.
tok = '\n'.join(l for l in open(D + 'tokens.css').read().split('\n') if not l.startswith('@font-face'))
fonts = [('Ubuntu', 500, 'Ubuntu-Medium'), ('Ubuntu', 700, 'Ubuntu-Bold'), ('Open Sans', 400, 'OpenSans-Regular'), ('Open Sans', 600, 'OpenSans-SemiBold'), ('Open Sans', 700, 'OpenSans-Bold')]
out = ['\n/* ===== CYP design system, version %s of the tokens (generated by mkds.py: do not edit by hand) ===== */' % T.get('version')]
for fam, w, f in fonts:
    b = base64.b64encode(open(D + 'fonts/' + f + '.woff2', 'rb').read()).decode()
    out.append("@font-face{font-family:'%s';font-weight:%d;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,%s) format('woff2')}" % (fam, w, b))
out.append('/* tokens.css of the design system, unchanged except for the @font-face rules */\n' + tok)
# names the old stylesheet of CYP EDU still uses, pointed at the tokens
out.append(':root{--muted:var(--ink-muted);--soft:var(--ink-muted);--line2:var(--line);--fill:var(--surface-soft);--fill2:var(--surface-soft);--pri:var(--blue);--pri2:var(--navy);--prisoft:var(--surface-soft);'
  '--green:var(--ok);--greensoft:var(--ok-soft);--orange:var(--warn);--orangesoft:var(--warn-soft);--red:var(--danger);--redsoft:var(--danger-soft)}')
out.append('/* components/bundle.css of the design system, unchanged */\n' + open(D + 'components/bundle.css').read())
out.append('/* how CYP EDU wears the system */\n' + open('ds.rules.css').read())
open('ds.css', 'w').write('\n'.join(out) + '\n'); print('ds.css', sum(len(x) for x in out))
# the web version loads the fonts as files (fonts/), kept by the service worker
web = [x for x in out if not x.startswith('@font-face')]
web[1:1] = ["@font-face{font-family:'%s';font-weight:%d;font-style:normal;font-display:swap;src:url(fonts/%s.woff2) format('woff2')}" % (fam, w, f) for fam, w, f in fonts]
open('ds.web.css', 'w').write('\n'.join(web) + '\n')
json.dump([f + '.woff2' for _, _, f in fonts], open('ds.fonts.json', 'w'))
# icons of the sections, copied from the ColourKey of the system
import re
key = open(D + 'components/ColourKey/preview.html').read()
ic = {name.strip(): svg for svg, name in re.findall(r'<li class="cyp-c-blue"><span class="cyp-disc cyp-disc--sm"><svg viewBox="0 0 24 24" aria-hidden="true">(.*?)</svg></span>([^<]+)</li>', key)}
def inner(svg): return svg[svg.index('>') + 1:svg.rindex('</svg>')]
def before(file, mark):   # the icon that stands right before a word
    h = open(D + 'components/' + file).read(); i = h.index('</svg>' + mark); j = h.rindex('<svg', 0, i); return inner(h[j:i + 6])
def after(file, mark):    # the icon that stands right after a word
    h = open(D + 'components/' + file).read(); j = h.index(mark + '<svg') + len(mark); i = h.index('</svg>', j); return inner(h[j:i + 6])
tools = {name.strip(): svg for svg, name in re.findall(r'<li><svg class="cyp-icon" viewBox="0 0 24 24" aria-hidden="true">(.*?)</svg>([^<]+)</li>', key)}
dsi = {'check': before('ListRow/preview.html', 'Present'), 'alert': before('Pager/preview.html', 'Not today'), 'down': after('ListRow/preview.html', 'Not marked'),
       'left': before('Pager/preview.html', 'Before'), 'right': after('Pager/preview.html', 'After'), 'x': before('Sheet/preview.html', 'Close'),
       'pin': before('InteractiveReport/preview.html', '</span><span class="heading-2">Luigi'),
       'more': tools['More'], 'comment': tools['Comment'], 'signout': tools['Sign out'], 'print': tools['Print'], 'excel': tools['Export in Excel'], 'clock': before('ListRow/preview.html', 'Waiting')}
# chevron-right that ends a row which opens a record (ListRow), arrow-right of the Referral route
_lr = open(D + 'components/ListRow/preview.html').read(); _i = _lr.index('<svg class="cyp-icon cyp-go"'); dsi['go'] = inner(_lr[_i:_lr.index('</svg>', _i) + 6])
_rf = open(D + 'components/Referral/preview.html').read(); _i = _rf.index('Sports <svg') + 7; dsi['arrow'] = inner(_rf[_i:_rf.index('</svg>', _i) + 6])
# icons of the places, on a disc in the colour of the place (ColourKey, 24/11)
place_ic = {cls: inner('<svg' + svg + '</svg>') for cls, svg in re.findall(r'<li class="cyp-c-(luigi|minsundu|nkwazi|community-school)"><span class="cyp-disc cyp-disc--sm"><svg(.*?)</svg>', key)}
open('dsicons.js', 'w').write("""/* icons of the sections and of the tools, classes of the places: from the CYP design system (generated by mkds.py) */
const SEC_ICON = %s;
const DS_ICON = %s;
const SEC_KEY = { Admin: 'Education office', 'Education office': 'Education office', Family: 'Family Section', 'Family Section': 'Family Section', School: 'School Section', 'School Section': 'School Section', UCC: 'UCC Children Section', Youth: 'Youth', Literacy: 'Literacy class', Counseling: 'Counselling', Counselling: 'Counselling', Sports: 'Sports', All: 'Family Section' };
/* a colour stands for a place. UCC, Youth and the Literacy class are sections held at Minsundu: listed as sections they show their icon on the blue disc */
const PLACE_CLASS = { Luigi: 'luigi', Minsundu: 'minsundu', Nkwazi: 'nkwazi', School: 'community-school' };
function dsIcon(k) { return '<svg class="cyp-icon" viewBox="0 0 24 24" aria-hidden="true">' + (DS_ICON[k] || '') + '</svg>'; }
function secDisc(k) { const svg = SEC_ICON[SEC_KEY[k] || k]; return svg ? '<span class="cyp-disc cyp-disc--sm cyp-c-blue"><svg viewBox="0 0 24 24" aria-hidden="true">' + svg + '</svg></span>' : ''; }
function pinDisc(cls, sm) { return '<span class="cyp-disc' + (sm ? ' cyp-disc--sm' : '') + (cls ? ' cyp-c-' + cls : '') + '"><svg viewBox="0 0 24 24" aria-hidden="true">' + DS_ICON.pin + '</svg></span>'; }
function placeSwatch(k) { return PLACE_CLASS[k] ? '<i class="cyp-swatch cyp-c-' + PLACE_CLASS[k] + '"></i>' : ''; }
/* each place shows its icon on a disc in its own colour (ColourKey of 24/11): Luigi door-open, Minsundu bed, Nkwazi Centre bird, Community school pencil-ruler */
const PLACE_ICON = %s;
function placeDisc(k) { return PLACE_ICON[k] && PLACE_CLASS[k] ? '<span class="cyp-disc cyp-disc--sm cyp-c-' + PLACE_CLASS[k] + '"><svg viewBox="0 0 24 24" aria-hidden="true">' + PLACE_ICON[k] + '</svg></span>' : ''; }
function keyMark(k) { return placeDisc(k) || placeSwatch(k) || secDisc(k); }
""" % (json.dumps(ic), json.dumps(dsi), json.dumps({k: place_ic[v] for k, v in {"Luigi": "luigi", "Minsundu": "minsundu", "Nkwazi": "nkwazi", "School": "community-school"}.items()})))
print('icons', len(ic), 'tools', sorted(dsi))
